async def get_tenant_id(x_tenant_id: str = Header(...)) -> str:
    if not x_tenant_id.strip():
        raise HTTPException(status_code=400, detail="X-Tenant-ID header is required")
    return x_tenant_id.strip()

if response.status_code == 429:
    retry_after = float(response.headers.get("Retry-After", 5))
    raise VendorRateLimited(retry_after=retry_after)

if body_size > max_body:
    return JSONResponse(
        status_code=413,
        content={"detail": "Request body too large"},
    )

if record.payload_hash != payload_hash:
    logger.warning("Idempotency conflict: tenant=%s", tenant_id)
    return None, True

except VendorRateLimited as exc:
    # Respect Retry-After — return to pending, don't count as failure attempt
    if await mark_retry(db, item.id, claimed_lease, item.attempt_count, exc.retry_after):
        logger.info("Item rate limited by vendor, retry after %.1fs: item=%s", exc.retry_after, item.id)
    else:
        logger.warning("Lost lease before mark_retry, skipping: item=%s", item.id)

if response.status_code == 429:
    retry_after = float(response.headers.get("Retry-After", 5))
    raise VendorRateLimited(retry_after=retry_after)

except VendorServerError as exc:
    new_attempt = item.attempt_count + 1
    if new_attempt >= settings.max_retry_count:
        if await mark_failed(db, item.id, claimed_lease, new_attempt, str(exc)):
            logger.warning("Item permanently failed: item=%s error=%s", item.id, exc)
        else:
            logger.warning("Lost lease before mark_failed, skipping: item=%s", item.id)

try:
    await db.commit()
except IntegrityError:
    # Lost a race: another concurrent request with the same
    # (tenant_id, idempotency_key) committed first. Re-run the exact
    # same idempotency check used on the normal path — single source
    # of truth for "same payload -> return batch" vs "different
    # payload -> 409" — rather than assuming the collision means
    # success.
    await db.rollback()
    existing_batch_id, conflict = await check_idempotency(
        db, tenant_id, idempotency_key, payload_hash
    )
    if conflict:
        raise HTTPException(status_code=409, detail="Idempotency key reused with different payload")
    if existing_batch_id:
        logger.info(
            "Idempotency race resolved: tenant=%s batch=%s", tenant_id, existing_batch_id
        )
        return BatchSubmitResponse(batch_id=existing_batch_id)
    # Unexpected integrity violation unrelated to idempotency.
    # Surface for investigation.
    raise

if not await item_lease_owner(db, item.id, claimed_lease):
    logger.warning("Lost lease before vendor call, skipping: item=%s", item.id)
    return

if await mark_done(db, item.id, claimed_lease, result):
    logger.info("Item done: item=%s", item.id)
else:
    logger.warning("Lost lease before mark_done, skipping: item=%s", item.id)

@router.get("/batches/{batch_id}/failures", response_model=BatchFailuresResponse)
async def get_batch_failures(
    batch_id: uuid.UUID,
    tenant_id: str = Depends(get_tenant_id),
    db: AsyncSession = Depends(get_db),
) -> BatchFailuresResponse:
    # Verify batch belongs to tenant
    result = await db.execute(
        select(Batch).where(Batch.id == batch_id, Batch.tenant_id == tenant_id)
    )
    if result.scalar_one_or_none() is None:
        raise HTTPException(status_code=404, detail="Batch not found")

    # Return only permanently failed items
    items_result = await db.execute(
        select(BatchItem.seq, BatchItem.attempt_count, BatchItem.error_message)
        .where(BatchItem.batch_id == batch_id, BatchItem.status == "failed")
        .order_by(BatchItem.seq)
    )

    return BatchFailuresResponse(
        batch_id=batch_id,
        items=[
            BatchFailureItem(
                seq=row.seq,
                attempt_count=row.attempt_count,
                last_error=row.error_message,
            )
            for row in items_result
        ],
    )
